Lang["Q1_10280"] = "送往沙塔斯的特殊货物"			-- https://cn.tbc.wowhead.com/?quest=10280
Lang["Q2_10280"] = "将阿塔玛水晶交给沙塔斯城圣光广场的阿达尔。"
Lang["Q1_10704"] = "如何杀入禁魔监狱"			-- https://cn.tbc.wowhead.com/?quest=10704
