Lang["Q2_6627"] = "成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。"
Lang["Q2_6628"] = "成功回答帕科瓦·芬塔拉斯的问题，然后再次和他对话。他会一直在幽暗城等你回答问题。"
Lang["Q2_6681"] = "把拉文霍德徽记交给拉文霍德庄园的法拉德，庄园就坐落在希尔斯布莱德的群山之中。\n\n你的智慧将在这次旅途中得到考验。做好准备吧。"
