Lang["Q2_7064"] = "杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。"
Lang["Q2_7065"] = "杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。"
Lang["Q2_7066"] = "到月光林地去找到雷姆洛斯，将生命之种交给他。"
Lang["Q2_7067"] = "阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。"
