Lang["Q2_7494"] = "与菲拉斯羽月要塞的拉托尼库斯·月矛谈一谈。"
Lang["Q2_7499"] = "将这本典籍交给它的主人。"
Lang["Q2_7506"] = "将这本典籍交给它的主人。"
Lang["Q2_7562"] = "与燃烧平原的莫苏尔·召血者谈一谈。"
Lang["Q2_7563"] = "把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。"
Lang["Q2_7564"] = "把血箱交给燃烧平原的戈瑟奇·邪眼。"
Lang["Q2_7581"] = "到菲拉斯的厄运之槌去，从扭木广场的荒野萨特身上找到15份萨特之血，然后把它们交给腐烂之痕的戴奥。"
Lang["Q2_7582"] = "到冬泉谷的暗语峡谷去，从盘踞在峡谷中的赫达琳恶魔身上找到5块赫达琳之泪。完成任务之后回到腐烂之痕的戴奥那里。"
Lang["Q2_7583"] = "在腐烂之痕中找到一个末日守卫指挥官。\n\n对其使用光芒水晶监牢。你要做好承受疯狂攻击的准备，那个恶魔会拼命挣扎试图逃脱。\n\n如果你成功了，就把被囚禁的末日守卫交给腐烂之痕的戴奥。"
Lang["Q2_7601"] = "与费伍德森林的伊普斯谈一谈。"
Lang["Q2_7602"] = "费伍德的伊普斯要求你从三个不同的地区收集三块无暇的恶魔精华，然后把它们交给他。\n\n艾萨拉的雷加斯萨特、费伍德森林的加德纳尔军团士兵和诅咒之地的地狱卫士斥候分别拥有一种无暇的恶魔精华。"
Lang["Q2_7603"] = "在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。\n\n把克罗苏斯的恶魔之核交给费伍德森林的尼比。"
Lang["Q2_7621"] = "警示"
Lang["Q2_7622"] = "在总计有15个农夫被杀死之前拯救50个农夫。完成任务之后与艾瑞斯·哈文法谈谈。\n\n你可以通过浏览死亡布告来了解自己拯救了多少农夫。"
Lang["Q2_7623"] = "从燃烧平原的戈瑟奇那里购买暗影药水。\n\n使用这种药剂进入加德纳尔，然后与魔王贝恩霍勒谈一谈。"
Lang["Q2_7624"] = "找到并杀死乌拉泰克，然后把叛徒之心交给加德纳尔的魔王贝恩霍勒。"
Lang["Q2_7625"] = "从乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。"
Lang["Q2_7626"] = "把10瓶暗影之力药剂交给燃烧平原的戈瑟奇·邪眼。"
Lang["Q2_7627"] = "把6份大块魔光碎片和25块黑铁矿石交给燃烧平原的戈瑟奇·邪眼。"
Lang["Q2_7628"] = "把35块黑龙鳞片交给燃烧平原的戈瑟奇·邪眼。"
Lang["Q2_7629"] = "把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。"
Lang["Q2_7630"] = "把3块奥金锭交给燃烧平原的戈瑟奇·邪眼。"
Lang["Q2_7631"] = "阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。"
Lang["Q2_7632"] = "找到远古石叶的主人。祝你好运，<name>。这个世界是很大的。"
Lang["Q2_7633"] = "简介"
Lang["Q2_7634"] = "费伍德森林的古树哈斯塔特要求你带回一块成年蓝龙的肌腱。"
Lang["Q2_7635"] = "费伍德森林的古树斯托玛要求你带给他一块成年黑龙的肌腱。"
Lang["Q2_7636"] = "你必须找到并干掉下列4个恶魔：\n\n迷人的西蒙妮。\n\n疯狂的克林弗兰。\n\nS屠杀者索伦诺尔。\n\n摧毁者阿托留斯。\n\n杀掉这些恶魔，然后回到费伍德森林的古树瓦特鲁斯那里去。\n\n根据你背包中的石化树皮来找到它们所在位置的线索。\n\n你必须独自完成这个任务。"
Lang["Q2_7637"] = "到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。"
Lang["Q2_7638"] = "与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。"
Lang["Q2_7639"] = "把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。"
Lang["Q2_7640"] = "使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。"
Lang["Q2_7641"] = "与暴风城矮人区的格瑞曼德·艾尔默谈一谈。"
Lang["Q2_7642"] = "把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币交给暴风城矮人区的格瑞曼德·艾尔默。"
Lang["Q2_7643"] = "你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。\n\n到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。"
Lang["Q2_7644"] = "将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。"
Lang["Q2_7645"] = "把制作魔法粮草所需要的重要材料：20块可口的魔法点心带给希尔斯布莱德丘陵的梅丽德丝·卡尔森。据说银色黎明会出售这种饼干。\n\n你还需要给她50金币来对她进行安抚。"
Lang["Q2_7646"] = "把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。"
Lang["Q2_7647"] = "在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。\n\n把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。"
Lang["Q2_7648"] = "把奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。"
Lang["Q2_7666"] = "重回尸骨储藏所"
Lang["Q2_7667"] = "如果你愿意帮助奥格瑞玛智慧谷的萨格尼，就将一块艾泽拉斯钻石和一块原始黑钻石交给他。"
Lang["Q2_7668"] = "在通灵学院的尸骨储藏所地下室中心使用预言水晶球，这样将会召来一些灵魂，你必须与它们交战。将这些灵魂击败，死亡骑士达克雷尔就会出现。\n\n击败达克雷尔，将他的头颅交给奥格瑞玛智慧谷的萨格尼。"
Lang["Q2_7669"] = "重回尸骨储藏所"
Lang["Q2_7670"] = "与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。"
Lang["Q2_79007"] = "前往贫瘠之地46, 73。与烧焦的残骸互动并接受任务。\n\n在西部荒野37, 50与钉死的木板互动来交付任务。离开前从那块木板接受垫脚石。"
Lang["Q2_79008"] = "前往西部荒野37, 50。与钉死的木板旁的烧焦的残骸互动并接受任务。\n\n在贫瘠之地46, 73的烧焦的残骸处交付任务，然后与那里的钉死的木板互动并接受垫脚石。"
Lang["Q2_79192"] = "部落在西部荒野37, 50的钉死的木板处接受此任务。联盟在贫瘠之地46, 73的钉死的木板处接受。\n\n前往石爪山脉51, 51。从道路进入山中的缺口，沿小路走到营地。与口袋杂物互动（40.8, 52.5）。"
Lang["Q2_79974"] = "与石爪山脉的土堆（39.6, 49.9）互动以接受此任务。\n\n前往洛克莫丹49, 12的水坝。跳到岩架上，与雕刻小像互动（49.5, 12.8）。"
Lang["Q2_79975"] = "与洛克莫丹水坝的雕刻小像（49.5, 12.8）互动以接受此任务。\n\n前往希尔斯布莱德丘陵81, 56。面向通往阿拉希高地的大门，向左转并沿着城墙走到倾覆的货车。沿跳跃谜题前往营地，然后与信使包互动（阿拉希高地 22.4, 24.2）。"
Lang["Q2_79976"] = "与信使包互动，再与它正下方草草卷起的背包互动，获得舒适的睡袋。"
Lang["Q2_79980"] = "在石爪营地与口袋杂物（40.8, 52.5）互动以接受此任务。\n\n穿过营地，从山上跳到有土堆的岩架（39.6, 49.9），然后与它互动。"
Lang["Q2_79987"] = "你可以留下这枚戒指，也可以去寻找在戒指内侧留下印记和铭文的人。"
Lang["Q2_80140"] = "你可以留下这枚戒指，也可以去寻找在戒指内侧留下印记和铭文的人。"
Lang["Q2_8151"] = "跟艾萨拉的奥汀克谈一谈。"
Lang["Q2_8153"] = "将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。"
Lang["Q2_8231"] = "将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。"
Lang["Q2_8232"] = "将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。"
Lang["Q2_8233"] = "前往拉文霍德庄园，和乔拉齐·拉文霍德公爵谈一谈。"
Lang["Q2_8234"] = "从艾萨拉的木喉萨满祭司那儿取回密封的蓝袋子，将它交给艾萨拉的大法师克希雷姆。"
Lang["Q2_8235"] = "将10块密文碎片交给艾萨拉的大法师克希雷姆。"
Lang["Q2_8236"] = "将碧蓝钥匙交给乔拉齐·拉文霍德公爵。"
Lang["Q2_8249"] = "垃圾箱"
Lang["Q2_8250"] = "找到萨纳斯，让他将你传送到大法师克希雷姆那儿。"
Lang["Q2_8251"] = "为大法师克希雷姆收集10份闪光尘埃。"
Lang["Q2_8252"] = "收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。"
Lang["Q2_8253"] = "从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。"
Lang["Q2_8254"] = "找到艾萨拉的奥汀克。"
Lang["Q2_8255"] = "收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。"
